/**
 * 权限相关中间件
 */
import { useUserStore } from '@/store/modules/user';
import { ROUTER_PERMISSION, ROUTER_PATHS } from '../constants';

/**
 * 权限验证中间件
 * @param {Object} to - 目标路由
 * @param {Object} from - 来源路由
 * @param {Function} next - 导航函数
 */
export const middleware_permission = async (to, from, next) => {
    const permissionLevel = to.meta?.permissionLevel || ROUTER_PERMISSION.PUBLIC;
    
    // 公开页面或需要登录的页面直接通过（登录验证由auth中间件处理）
    if (permissionLevel === ROUTER_PERMISSION.PUBLIC || 
        permissionLevel === ROUTER_PERMISSION.AUTH_LOGIN) {
        return next();
    }
    
    // 需要管理员权限
    if (permissionLevel === ROUTER_PERMISSION.ADMIN) {
        const userStore = useUserStore();
        const isAdmin = userStore.isAdmin;
    
        if (!isAdmin) {
            return next({ path: ROUTER_PATHS.HOME });
        }
    }
    
    console.log('🛡️ [PERMISSION MIDDLEWARE] ✅ 权限验证通过，继续执行');
    next();
}; 