/**
 * 用户相关数据模型
 * 包含用户账户、登录、偏好等所有相关模型
 */
import { formatDateMDY_MonthAbbreviation } from '@/utils/util';
import { BaseResponseData } from './base-models';



/**
 * 用户登录信息模型
 */
export class UserLoginInfo extends BaseResponseData {
    access_token: string = '';
    token_type: string = 'bearer';

    get authorizationHeader(): string {
        return `${this.token_type} ${this.access_token}`;
    }
} 

/**
 * 用户账户信息模型
 * 对应API返回的UserInDB数据结构
 */
export class UserInfo extends BaseResponseData {
    /** 用户ID */
    id: number = 0;
    /** 用户邮箱 */
    email: string = '';
    /** 用户昵称 */
    nickname: string | null = null;
    /** 创建时间 */
    created_at: string = '';
    /** 是否为管理员（具有系统管理权限） */
    is_admin: boolean = false;
    /** 用户头像 */
    avatar: string = '';
    
    get displayAvatar(): string {
        return this.avatar || '/static/images/default_avatar.png';
    }

    get loginMethod(): string {
        return this.email ? 'Email' : 'Other';
    }

    get displayCreatedAt_MDY_MonthAbbreviation(): string {
        return formatDateMDY_MonthAbbreviation(this.created_at);
    }
}

export class Hello extends BaseResponseData {
    access_token: string = '';
    token_type: string = 'bearer';
}