/**
 * 媒体生成相关API服务
 * 提供文本生成图像、文本生成视频、状态查询、结果获取等功能
 */
import { ApiClient } from './client-api';
import { ApiResponse } from './definitions';
import {
    API_GENERATION_TEXT_TO_IMAGE,
    API_GENERATION_TEXT_TO_VIDEO,
    API_GENERATION_IMAGE_TO_VIDEO,
    API_GENERATION_STATUS,
    API_GENERATION_RESULT,
    API_GENERATION_HISTORY,
    API_GENERATION_FAVORITES,
    API_GENERATION_FAVORITE_TOGGLE,
    API_GENERATION_DELETE
} from './api-url';
import { 
    FavoritesQueryParams, 
    FavoritesListResponse, 
    GenerationHistoryQueryParams, 
    GenerationHistoryListResponse,
    TransformedImageData,
    TransformedVideoData,
    TransformedPaginationData
} from '../models/ai-media-models';
import { GenericResponseData } from '../models/base-models';

/**
 * 文本生成图像请求参数
 */
export interface TextToImageRequest {
    prompt: string;              // 图像生成提示词（必填）
    negative_prompt: string;     // 负面提示词（必填）
    model: string;              // 生成模型（必填）
    aspect_ratio?: string;       // 图像纵横比（仅XMIND-G-IMAGEN-3模型时传入）
}

/**
 * 文本生成视频请求参数
 */
export interface TextToVideoRequest {
    prompt: string;              // 提示词（必填）
    model: string;               // 使用的模型（必填）
    duration: number;            // 视频时长（秒）（必填）
    aspect_ratio: string;        // 视频比例，如 "16:9"（必填）
    negative_prompt: string;     // 负面提示词（必填，固定传空字符串）
}

/**
 * 图像生成视频请求参数
 */
export interface ImageToVideoRequest {
    source_image_url: string;    // 源图像URL（必填）
    prompt: string;              // 提示词（必填）
    model: string;               // 使用的模型（必填）
    duration: number;            // 视频时长（秒）（必填）
    aspect_ratio: string;        // 视频比例，如 "16:9"（必填）
    negative_prompt: string;     // 负面提示词（必填，固定传空字符串）
}

/**
 * 生成任务响应
 */
export interface GenerationTaskResponse {
    task_id: string;           // 任务ID
    status: string;           // 任务状态
    message?: string;         // 状态消息
}

/**
 * 任务状态响应
 */
export interface TaskStatusResponse {
    task_id: string;          // 任务ID
    status: string;          // 任务状态：pending, processing, completed, failed
    progress: number;        // 进度百分比 0-100
    message?: string;        // 状态消息
    estimated_time?: number; // 预估剩余时间（秒）
}

/**
 * 任务结果响应
 */
export interface TaskResultResponse {
    task_id: string;         // 任务ID
    status: string;         // 任务状态
    result?: {
        image_url?: string;  // 图片结果URL
        video_url?: string;  // 视频结果URL
        image_urls?: string[]; // 多张图片结果URLs
        video_urls?: string[]; // 多个视频结果URLs
    };
    error?: string;         // 错误信息
}

// ==================== 收藏相关接口参数 ====================

/**
 * 收藏切换请求参数接口
 * 少于4个参数，使用基础类型
 */
export interface FavoriteToggleParams {
    /** 媒体ID */
    media_id: string;
}

/**
 * 删除生成任务请求参数接口
 */
export interface GenerationDeleteParams {
    /** 任务ID */
    task_id: string;
}


/**
 * API生成服务类
 * 严格按照封装规范实现：静态方法、传递ResponseClass、返回ApiResponse类型
 */
export class ApiGeneration {
    /**
     * 文本生成图像
     */
    async textToImage(params: TextToImageRequest): Promise<GenerationTaskResponse> {
        const response = await ApiClient.post<any>(API_GENERATION_TEXT_TO_IMAGE, params);
        return response.data;
    }

    /**
     * 文本生成视频
     */
    async textToVideo(params: TextToVideoRequest): Promise<GenerationTaskResponse> {
        const response = await ApiClient.post<any>(API_GENERATION_TEXT_TO_VIDEO, params);
        return response.data;
    }

    /**
     * 图像生成视频
     */
    async imageToVideo(params: ImageToVideoRequest): Promise<GenerationTaskResponse> {
        const response = await ApiClient.post<any>(API_GENERATION_IMAGE_TO_VIDEO, params);
        return response.data;
    }

    /**
     * 获取任务状态
     */
    async getTaskStatus(params: object, showErrorMessage: boolean = false): Promise<TaskStatusResponse> {
        const response = await ApiClient.post<any>(API_GENERATION_STATUS, params, undefined, showErrorMessage);
        return response.data;
    }

    /**
     * 获取任务结果
     */
    async getTaskResult(params: object): Promise<TaskResultResponse> {
        const response = await ApiClient.post<any>(API_GENERATION_RESULT, params);
        return response.data;
    }

    // ==================== 媒体生成静态方法 ====================

    /**
     * 文本生成图像（静态方法）
     * @param params 文本生成图像请求参数
     * @returns 生成任务响应数据
     */
    static async textToImageStatic(params: TextToImageRequest): Promise<ApiResponse<any>> {
        return await ApiClient.post(API_GENERATION_TEXT_TO_IMAGE, params);
    }

    /**
     * 文本生成视频（静态方法）
     * @param params 文本生成视频请求参数
     * @returns 生成任务响应数据
     */
    static async textToVideoStatic(params: TextToVideoRequest): Promise<ApiResponse<any>> {
        return await ApiClient.post(API_GENERATION_TEXT_TO_VIDEO, params);
    }

    /**
     * 图像生成视频（静态方法）
     * @param params 图像生成视频请求参数
     * @returns 生成任务响应数据
     */
    static async imageToVideoStatic(params: ImageToVideoRequest): Promise<ApiResponse<any>> {
        return await ApiClient.post(API_GENERATION_IMAGE_TO_VIDEO, params);
    }

    /**
     * 获取任务状态（静态方法）
     * @param taskId 任务ID
     * @param showErrorMessage 是否显示错误消息
     * @returns 任务状态响应数据
     */
    static async getTaskStatusStatic(taskId: string, showErrorMessage: boolean = false): Promise<ApiResponse<any>> {
        return await ApiClient.post(API_GENERATION_STATUS, { task_id: taskId }, undefined, showErrorMessage);
    }

    /**
     * 获取任务结果（静态方法）
     * @param taskId 任务ID
     * @returns 任务结果响应数据
     */
    static async getTaskResultStatic(taskId: string): Promise<ApiResponse<any>> {
        return await ApiClient.post(API_GENERATION_RESULT, { task_id: taskId });
    }

    // ==================== 收藏相关静态方法 ====================

    /**
     * 获取收藏媒体列表
     * @param params 查询参数（包含4个参数，使用接口定义）
     * @returns 收藏列表响应数据
     */
    static async getFavorites(params?: FavoritesQueryParams): Promise<ApiResponse<FavoritesListResponse>> {
        return await ApiClient.post(API_GENERATION_FAVORITES, params, FavoritesListResponse);
    }

    /**
     * 获取生成历史列表
     * @param params 查询参数（包含4个参数，使用专门的历史查询接口定义）
     * @returns 历史列表响应数据
     */
    static async getHistory(params?: GenerationHistoryQueryParams): Promise<ApiResponse<GenerationHistoryListResponse>> {
        return await ApiClient.post(API_GENERATION_HISTORY, params, GenerationHistoryListResponse);
    }

    /**
     * 切换媒体收藏状态
     * @param mediaId 媒体ID
     * @returns 通用响应数据
     */
    static async toggleFavorite(mediaId: string): Promise<ApiResponse<GenericResponseData>> {
        const params: FavoriteToggleParams = {
            media_id: mediaId
        };
        return await ApiClient.post(API_GENERATION_FAVORITE_TOGGLE, params, GenericResponseData);
    }

    /**
     * 删除生成任务
     * @param taskId 任务ID
     * @returns 通用响应数据
     */
    static async deleteGeneration(taskId: string): Promise<ApiResponse<GenericResponseData>> {
        const params: GenerationDeleteParams = {
            task_id: taskId
        };
        return await ApiClient.post(API_GENERATION_DELETE, params, GenericResponseData);
    }

    // ==================== 数据转换静态方法 ====================

    /**
     * 格式化日期为页面显示格式
     * @param dateString - ISO日期字符串
     * @returns 格式化后的日期字符串
     */
    private static formatDate(dateString: string): string {
        if (!dateString) return '';

        try {
            const date = new Date(dateString);
            return date.toISOString().split('T')[0]; // 返回 YYYY-MM-DD 格式
        } catch (error) {
            console.warn('Date format error:', error);
            return '';
        }
    }

    /**
     * 格式化文件大小
     * @param bytes - 文件大小（字节）
     * @returns 格式化后的文件大小
     */
    private static formatFileSize(bytes: number): string {
        if (!bytes || bytes === 0) return '0B';

        const units = ['B', 'KB', 'MB', 'GB'];
        let size = bytes;
        let unitIndex = 0;

        while (size >= 1024 && unitIndex < units.length - 1) {
            size /= 1024;
            unitIndex++;
        }

        return `${size.toFixed(1)}${units[unitIndex]}`;
    }

    /**
     * 格式化视频时长
     * @param seconds - 视频时长（秒）
     * @returns 格式化后的时长字符串
     */
    private static formatVideoDuration(seconds: number): string {
        if (!seconds || seconds === 0) return '0:00 / 0:05';

        const minutes = Math.floor(seconds / 60);
        const remainingSeconds = Math.floor(seconds % 60);
        const formattedTime = `${minutes}:${String(remainingSeconds).padStart(2, '0')}`;

        return `0:00 / ${formattedTime}`;
    }

    /**
     * 根据宽高比获取推荐分辨率
     * @param aspectRatio - 宽高比，如 "16:9", "9:16", "1:1"
     * @returns 推荐分辨率
     */
    private static getResolutionFromAspectRatio(aspectRatio: string): string {
        if (!aspectRatio) return '1920x1080';
        
        const ratioMap: Record<string, string> = {
            '16:9': '1920x1080',
            '9:16': '1080x1920', 
            '1:1': '1080x1080',
            '4:3': '1440x1080',
            '3:4': '1080x1440'
        };
        
        return ratioMap[aspectRatio] || '1920x1080';
    }

    /**
     * 根据宽高获取分辨率等级
     * @param width - 宽度
     * @param height - 高度
     * @returns 分辨率等级
     */
    private static getResolutionLevel(width: number, height: number): string {
        if (!width || !height) return 'HD';

        const totalPixels = width * height;

        if (totalPixels >= 3840 * 2160) return '4K';
        if (totalPixels >= 2560 * 1440) return '2K';
        if (totalPixels >= 1920 * 1080) return 'Full HD';
        return 'HD';
    }

    /**
     * 根据宽高获取尺寸比例
     * @param width - 宽度
     * @param height - 高度
     * @returns 尺寸比例
     */
    private static getDimensionRatio(width: number, height: number): string {
        if (!width || !height) return '16:9';

        const ratio = width / height;

        if (Math.abs(ratio - 16/9) < 0.1) return '16:9';
        if (Math.abs(ratio - 9/16) < 0.1) return '9:16';
        if (Math.abs(ratio - 1) < 0.1) return '1:1';
        if (Math.abs(ratio - 4/3) < 0.1) return '4:3';
        if (Math.abs(ratio - 3/4) < 0.1) return '3:4';

        return `${width}:${height}`;
    }

    /**
     * 将生成结果转换为图片数据格式
     * @param generationResults - API返回的生成结果列表
     * @returns 转换后的图片数据列表
     */
    static transformToImageData(generationResults: any[]): TransformedImageData[] {
        if (!Array.isArray(generationResults)) {
            console.warn('Invalid generation results:', generationResults);
            return [];
        }

        // 过滤并转换数据
        return generationResults
            .filter(item => {
                // 过滤出图片类型的数据
                const isImageItem = item.media_type === 'image';
                const hasValidId = item.id;
                return isImageItem && hasValidId;
            })
            .map(item => {
                const mediaMetadata = item.media_metadata || {};


                // 获取提示词
                const originalPrompt = item.prompt || ''; // 用户原始提示词
                const revisedPrompt = mediaMetadata?.revised_prompt || ''; // AI优化提示词
                const description = originalPrompt || revisedPrompt || 'No description available'; // 列表显示优先使用原始提示词

                return {
                    id: item.id,
                    imageUrl: item.file_url || '',
                    description: description, // 列表中显示用户原始提示词
                    createdDate: this.formatDate(item.created_at),
                    prompt: originalPrompt, // 详情中显示用户原始提示词
                    originalPrompt: originalPrompt, // 用户原始提示词
                    revisedPrompt: revisedPrompt, // AI优化提示词
                    model: item.model, // 模型信息
                    generationType: item.generation_type, // 生成类型
                    resolution: this.getResolutionLevel(mediaMetadata?.width, mediaMetadata?.height),
                    dimensions: this.getDimensionRatio(mediaMetadata?.width, mediaMetadata?.height),
                    seed: null, // 新接口暂无seed信息
                    isFavorited: item.is_favorited || false,
                    mediaId: item.id, // 用于收藏操作
                    // 保留原始API数据用于详情页面
                    originalApiData: item,
                    // 增强功能相关数据（默认值）
                    canEnhance: true,
                    enhancedUrl: null,
                    enhanceConfig: {
                        scale: 2.00,
                        prompt: '',
                        negativePrompt: '',
                        creativity: 0.3,
                        handFix: false,
                        seed: null
                    },
                    // 放大功能相关数据
                    zoomConfig: {
                        scale: 2.00
                    }
                };
            });
    }

    /**
     * 将生成结果转换为视频数据格式
     * @param generationResults - API返回的生成结果列表
     * @returns 转换后的视频数据列表
     */
    static transformToVideoData(generationResults: any[]): TransformedVideoData[] {
        if (!Array.isArray(generationResults)) {
            console.warn('Invalid generation results:', generationResults);
            return [];
        }

        // 过滤并转换数据
        return generationResults
            .filter(item => {
                // 过滤出视频类型的数据
                const isVideoItem = item.media_type === 'video';
                const hasValidId = item.id;
                return isVideoItem && hasValidId;
            })
            .map(item => {
                const mediaMetadata = item.media_metadata || {};


                // 获取提示词
                const originalPrompt = item.prompt || ''; // 用户原始提示词
                const description = originalPrompt || ''; // 列表显示用户原始提示词

                // 获取视频比例：直接从metadata的aspect_ratio字段获取
                const aspectRatio = mediaMetadata?.aspect_ratio || '';

                // 获取时长（如果有的话）
                const duration = mediaMetadata?.duration || 5;

                // 直接使用file_url作为视频地址
                const videoUrl = item.file_url || '';

                // 获取源图片（对于image_to_video类型）
                const sourceImage = mediaMetadata?.source_image || null;

                return {
                    id: item.id,
                    description: description, // 列表中显示用户原始提示词
                    createdDate: this.formatDate(item.created_at),
                    // 对于视频，缩略图暂时使用视频文件本身，后续可优化为获取视频第一帧
                    thumbnailUrl: videoUrl,
                    videoUrl: videoUrl,
                    duration: this.formatVideoDuration(duration),
                    fileSize: item.file_size ? this.formatFileSize(item.file_size) : '0MB',
                    // 从实际数据获取分辨率，如无则为undefined
                    resolution: mediaMetadata?.width && mediaMetadata?.height ? this.getResolutionFromAspectRatio(aspectRatio) : undefined,
                    format: mediaMetadata?.format?.toUpperCase() || '',
                    isFavorited: item.is_favorited || false,
                    mediaId: item.id, // 用于收藏操作
                    generationType: item.generation_type || '', // 生成类型
                    sourceImage: sourceImage, // 源图片（image_to_video专用）
                    // 由于新接口没有任务状态，默认认为都是completed
                    taskStatus: 'completed',
                    errorMessage: '',
                    // 保留原始API数据用于详情页面
                    originalApiData: item,
                    // 详情配置信息
                    videoConfig: {
                        prompt: originalPrompt, // 用户原始提示词
                        model: item.model || '', // 模型信息
                        generationType: item.generation_type || '', // 生成类型
                        resolution: mediaMetadata?.width && mediaMetadata?.height ? `${mediaMetadata.width}x${mediaMetadata.height}` : undefined,
                        dimensions: aspectRatio,
                        frameRate: mediaMetadata?.fps ? `${mediaMetadata.fps}FPS` : undefined,
                        duration: `${duration}s`,
                        seed: undefined, // 新接口暂无seed信息，设为undefined而不是随机数
                        aspectRatio: aspectRatio,
                        negativePrompt: '', // 新接口暂无negativePrompt信息
                        sourceImage: sourceImage, // 源图片（image_to_video专用）
                        status: 'completed',
                        errorMessage: ''
                    }
                };
            });
    }

    /**
     * 转换分页数据
     * @param apiResponse - API返回的分页响应
     * @returns 转换后的分页数据
     */
    static transformPaginationData<T>(apiResponse: any): TransformedPaginationData<T> {
        if (!apiResponse || !apiResponse.data) {
            return {
                items: [],
                total: 0,
                currentPage: 1,
                pageSize: 20,
                hasMore: false
            };
        }

        const { data } = apiResponse;

        return {
            items: data.items || [],
            total: data.total || 0,
            currentPage: data.page || 1,
            pageSize: data.page_size || 20,
            hasMore: data.has_more || false
        };
    }
}

// 导出API实例
export const apiGeneration = new ApiGeneration(); 