import { mediaTaskEventBus } from './media-task-events';
import { getStorage, setStorage } from '../utils/storage';
import { apiGeneration } from '../api/api-generation';
import router from '../router';

// 全局通知函数变量
let globalNotificationFunction: Function | null = null;

/**
 * 任务类型枚举
 */
export enum TaskType {
    IMAGE = 'image',
    VIDEO = 'video'
}

// 任务状态
type TaskStatus = 'pending' | 'processing' | 'completed' | 'failed';

// 任务模型
interface Task {
  taskId: string;
  type: TaskType;
  status: TaskStatus;
  progress: number;
  lastPolled: number;
  retryCount: number;
  timerId?: number; // setTimeout 的 ID
  customInterval?: number; // 自定义轮询间隔
}

/**
 * 任务通知工具
 * 根据当前页面状态智能选择通知方式
 */
class TaskNotificationHelper {
    /**
     * 获取当前活动的任务ID
     */
    private static getCurrentActiveTaskId(): string | null {
        try {
            const currentRoute = router.currentRoute.value;
            return (currentRoute.meta?.taskId as string) || null;
        } catch (error) {
            console.warn("Failed to get current route:", error);
            return null;
        }
    }

    /**
     * 检查任务是否为当前活动任务
     */
    private static isActiveTask(taskId: string): boolean {
        const activeTaskId = this.getCurrentActiveTaskId();
        return activeTaskId === taskId;
    }

    /**
     * 获取任务类型的显示名称
     */
    private static getTaskTypeName(taskType: TaskType): string {
        const typeNames: Record<TaskType, string> = {
            [TaskType.IMAGE]: "Image Generation",
            [TaskType.VIDEO]: "Video Generation",
        };

        return typeNames[taskType] || "Generation Task";
    }

    /**
     * 处理任务完成通知
     */
    public static async handleTaskCompleted(data: {
        taskId: string;
        type: TaskType;
        result?: any;
    }): Promise<void> {
        const { taskId, type } = data;
        // 任务完成时，调用getTaskResult获取实际结果数据
        const result = await apiGeneration.getTaskResult({
            task_id: taskId,
        });

        console.log(`Task ${taskId} completed, result:`, result);

        if (TaskNotificationHelper.isActiveTask(taskId)) {
            // 如果是当前活动任务，通过事件总线通知页面
            // 任务完成
            mediaTaskEventBus.emit("task-completed", {
                taskId: taskId,
                type: type,
                result: result,
            });
        } else {
            // 如果不是当前活动任务，显示全局通知
            TaskNotificationHelper.showCompletedNotification(taskId, type);
        }
    }

    /**
     * 处理任务失败通知
     */
    public static handleTaskFailed(data: {
        taskId: string;
        type: TaskType;
        error: string;
    }): void {
        const { taskId, type, error } = data;

        console.log(`Task ${taskId} failed with error:`, error);

        if (TaskNotificationHelper.isActiveTask(taskId)) {
            // 如果是当前活动任务，通过事件总线通知页面
            mediaTaskEventBus.emit("task-failed", {
                taskId: taskId,
                type: type,
                error: error,
            });
        } else {
            // 如果不是当前活动任务，显示全局通知
            TaskNotificationHelper.showFailedNotification(taskId, type, error);
        }
    }

    /**
     * 显示任务完成通知
     */
    private static showCompletedNotification(
        taskId: string,
        type: TaskType
    ): void {
        const typeName = this.getTaskTypeName(type);

        if (globalNotificationFunction) {
            globalNotificationFunction({
                title: "Task Completed",
                message: `Your ${typeName.toLowerCase()} has been completed successfully!`,
                type: "success",
                duration: 5000,
                position: "top-right",
            });
        }
    }

    /**
     * 显示任务失败通知
     */
    private static showFailedNotification(
        taskId: string,
        type: TaskType,
        error: string
    ): void {
        const typeName = this.getTaskTypeName(type);

        if (globalNotificationFunction) {
            globalNotificationFunction({
                title: "Task Failed",
                message: `Your ${typeName.toLowerCase()} failed: ${error}`,
                type: "error",
                duration: 8000,
                position: "top-right",
            });
        }
    }
}

/**
 * 媒体任务轮询服务
 * 负责所有媒体生成任务的轮询和通知
 * 支持 localStorage 持久化和智能轮询间隔
 */
export class MediaTaskPolling {
  // 单例实例
  private static instance: MediaTaskPolling;
  
  // 任务列表
  private taskList: Map<string, Task> = new Map();
  
  // 默认轮询间隔配置（毫秒）
  private readonly DEFAULT_INTERVALS: Record<TaskType, number> = {
    [TaskType.IMAGE]: 1000,         // 图片生成 1 秒
    [TaskType.VIDEO]: 10000         // 视频生成 10 秒
  };
  
  // 最大重试次数
  private readonly MAX_RETRY_COUNT = 5;
  
  // localStorage 存储键
  private readonly STORAGE_KEY = 'task_polling_list';
  
  /**
   * 私有构造函数
   */
  private constructor() {
  
  }
  
  /**
   * 获取单例实例
   */
  private static getInstance(): MediaTaskPolling {
    if (!MediaTaskPolling.instance) {
      MediaTaskPolling.instance = new MediaTaskPolling();
    }
    return MediaTaskPolling.instance;
  }
  
  /**
   * 初始化管理器
   * 从 localStorage 加载任务列表并恢复轮询
   */
  private init(): void {
    this.loadTasksFromStorage();
    this.resumeAllTasks();
  }
  
  /**
   * 添加任务
   * @param taskId 任务ID
   * @param type 任务类型
   * @param customInterval 自定义轮询间隔（毫秒）
   */
  private addTask(taskId: string, type: TaskType, customInterval?: number): void {
    const task: Task = {
      taskId,
      type,
      status: 'pending',
      progress: 0,
      lastPolled: Date.now(),
      retryCount: 0,
      customInterval
    };
    
    this.taskList.set(taskId, task);
    this.saveTasksToStorage();
    
    // 立即开始轮询
    this.startTaskPollingImmediately(task);
  }
  
  /**
   * 移除任务
   * @param taskId 任务ID
   */
  private removeTask(taskId: string): void {
    const task = this.taskList.get(taskId);
    if (task) {
      // 清除定时器
      if (task.timerId) {
        clearTimeout(task.timerId);
      }
      
      // 从任务列表中移除
      this.taskList.delete(taskId);
      this.saveTasksToStorage();
    }
  }
  
  /**
   * 获取任务信息
   * @param taskId 任务ID
   */
  private getTask(taskId: string): Task | undefined {
    return this.taskList.get(taskId);
  }
  
  /**
   * 获取所有任务
   */
  private getAllTasks(): Task[] {
    return Array.from(this.taskList.values());
  }
  
  /**
   * 立即开始任务轮询
   * @param task 任务对象
   */
  private async startTaskPollingImmediately(task: Task): Promise<void> {
    // 先清除之前的定时器
    if (task.timerId) {
      clearTimeout(task.timerId);
    }
    
    // 立即执行一次轮询
    console.log(`Starting immediate polling for task ${task.taskId}`);
    await this.pollTaskStatus(task);
  }

  /**
   * 开始任务轮询
   * @param task 任务对象
   */
  private startTaskPolling(task: Task): void {
    // 先清除之前的定时器
    if (task.timerId) {
      clearTimeout(task.timerId);
    }
    
    // 获取轮询间隔
    const interval = this.getPollingInterval(task);
    
    // 设置新的定时器
    task.timerId = window.setTimeout(() => {
      this.pollTaskStatus(task);
    }, interval);
    
    // 更新任务对象
    this.taskList.set(task.taskId, task);
  }
  
  /**
   * 轮询任务状态
   * @param task 任务对象
   */
  private async pollTaskStatus(task: Task): Promise<void> {
    try {
      // 更新最后轮询时间
      task.lastPolled = Date.now();
      const params = {
        task_id: task.taskId,
      }
      
      // 调用真实的状态查询 API
      const statusResponse = await apiGeneration.getTaskStatus(params, false);
      
      // 更新任务状态
      task.status = statusResponse.status as TaskStatus;
      task.progress = statusResponse.progress;
      
      // 更新任务列表
      this.taskList.set(task.taskId, task);
      
      // 根据状态处理任务
      await this.handleTaskStatusUpdate(task, statusResponse);
      
    } catch (error) {
      console.error(`Error polling task ${task.taskId}:`, error);
      await this.handleTaskError(task, error as Error);
    }
  }
  
  /**
   * 处理任务状态更新
   * @param task 任务对象
   * @param statusData 状态数据
   */
  private async handleTaskStatusUpdate(task: Task, statusData: any): Promise<void> {
    // 触发状态更新事件
    mediaTaskEventBus.emit('task-status-update', {
      taskId: task.taskId,
      type: task.type,
      status: task.status,
      res: statusData
    });

    switch (task.status) {
      case 'completed':
        // 任务完成时，调用统一的完成处理方法
        await TaskNotificationHelper.handleTaskCompleted({
          taskId: task.taskId,
          type: task.type
        });
        this.removeTask(task.taskId); // removeTask 内部会调用 saveTasksToStorage
        break;
        
      case 'failed':
        // 任务失败时，调用统一的失败处理方法
        TaskNotificationHelper.handleTaskFailed({
          taskId: task.taskId,
          type: task.type,
          error: statusData.error || 'Task failed'
        });
        this.removeTask(task.taskId); // removeTask 内部会调用 saveTasksToStorage
        break;
        
      case 'processing':
      case 'pending':
        // 任务进行中，重置重试计数并继续轮询
        task.retryCount = 0;
        this.taskList.set(task.taskId, task);
        this.startTaskPolling(task);
        break;
        
      default:
        console.warn(`Unknown task status: ${task.status}`);
        this.taskList.set(task.taskId, task);
        this.startTaskPolling(task);
        break;
    }
  }
  
  /**
   * 处理任务错误
   * @param task 任务对象
   * @param error 错误对象
   */
  private async handleTaskError(task: Task, error: Error): Promise<void> {
    task.retryCount++;
    
    if (task.retryCount >= this.MAX_RETRY_COUNT) {
      // 达到最大重试次数，标记为失败
      TaskNotificationHelper.handleTaskFailed({
        taskId: task.taskId,
        type: task.type,
        error: `Failed after ${this.MAX_RETRY_COUNT} retries: ${error.message}`
      });
      
      this.removeTask(task.taskId); // removeTask 内部会调用 saveTasksToStorage
    } else {
      // 继续重试
      console.log(`Retrying task ${task.taskId}, attempt ${task.retryCount}/${this.MAX_RETRY_COUNT}`);
      this.taskList.set(task.taskId, task);
      this.startTaskPolling(task);
    }
  }
  
  /**
   * 获取轮询间隔
   * @param task 任务对象
   */
  private getPollingInterval(task: Task): number {
    // 使用自定义间隔或默认间隔
    const baseInterval = task.customInterval || this.DEFAULT_INTERVALS[task.type];
    
    // 根据重试次数调整间隔（指数退避）
    const retryMultiplier = Math.pow(1.5, task.retryCount);
    
    return Math.min(baseInterval * retryMultiplier, 60000); // 最大60秒
  }
  
  /**
   * 从 localStorage 加载任务列表
   */
  private loadTasksFromStorage(): void {
    try {
      const stored = getStorage(this.STORAGE_KEY);
      if (stored && Array.isArray(stored)) {
        const allStoredTaskIds: string[] = [];
        const loadedTaskIds: string[] = [];
        
        stored.forEach((taskData: any) => {
          allStoredTaskIds.push(taskData.taskId);
          
          const task: Task = {
            taskId: taskData.taskId,
            type: taskData.type,
            status: taskData.status,
            progress: taskData.progress || 0,
            lastPolled: taskData.lastPolled || Date.now(),
            retryCount: taskData.retryCount || 0,
            customInterval: taskData.customInterval
          };
          
          // 只恢复未完成的任务
          if (task.status === 'pending' || task.status === 'processing') {
            this.taskList.set(task.taskId, task);
            loadedTaskIds.push(task.taskId);
          }
        });
      }
    } catch (error) {
      console.error('Failed to load tasks from storage:', error);
    }
  }
  
  /**
   * 保存任务列表到 localStorage
   */
  private saveTasksToStorage(): void {
    try {
      const tasksArray = Array.from(this.taskList.values()).map(task => ({
        taskId: task.taskId,
        type: task.type,
        status: task.status,
        progress: task.progress,
        lastPolled: task.lastPolled,
        retryCount: task.retryCount,
        customInterval: task.customInterval
      }));
      
      setStorage(this.STORAGE_KEY, tasksArray);
    } catch (error) {
      console.error('Failed to save tasks to storage:', error);
    }
  }
  
  /**
   * 恢复所有任务的轮询
   */
  private resumeAllTasks(): void {
    this.taskList.forEach(task => {
      this.startTaskPolling(task);
    });
    
    console.log(`Resumed polling for ${this.taskList.size} tasks`);
  }
  
  // 静态方法 - 供外部调用
  
  /**
   * 初始化媒体任务轮询
   * @param notificationFunction 通知函数 (PC端传入ElNotification，移动端传入showNotificationBase)
   */
  public static initPolling(notificationFunction: Function): void {
    // 设置全局通知函数
    globalNotificationFunction = notificationFunction;
    
    const polling = MediaTaskPolling.getInstance();
    polling.init();
  }
  
  /**
   * 添加任务到轮询
   */
  public static addTask(taskId: string, type: TaskType, customInterval?: number): void {
    const polling = MediaTaskPolling.getInstance();
    polling.addTask(taskId, type, customInterval);
  }
  
  /**
   * 移除任务
   */
  public static removeTask(taskId: string): void {
    const polling = MediaTaskPolling.getInstance();
    polling.removeTask(taskId);
  }
  
  /**
   * 获取任务信息
   */
  public static getTask(taskId: string): Task | undefined {
    const polling = MediaTaskPolling.getInstance();
    return polling.getTask(taskId);
  }
  
  /**
   * 获取所有任务
   */
  public static getAllTasks(): Task[] {
    const polling = MediaTaskPolling.getInstance();
    return polling.getAllTasks();
  }
}

// 导出便捷方法
export const initMediaTaskPolling = (notificationFunction: Function) => MediaTaskPolling.initPolling(notificationFunction);
export const addTaskToPolling = MediaTaskPolling.addTask;
export const removeTaskFromPolling = MediaTaskPolling.removeTask;
export const getTaskInfo = MediaTaskPolling.getTask;
export const getAllTaskInfo = MediaTaskPolling.getAllTasks; 