/**
 * 路由中间件管理器类
 */
class MiddlewareManager {
    constructor() {
        this.middlewares = [];
    }
    
    /**
     * 注册中间件
     * @param {Function} middleware - 中间件函数
     * @returns {MiddlewareManager} 返回自身以支持链式调用
     */
    use(middleware) {
        this.middlewares.push(middleware);
        return this;
    }
    
    /**
     * 执行中间件链
     * @param {Object} to - 目标路由
     * @param {Object} from - 来源路由
     * @param {Function} next - 导航函数
     */
    async execute(to, from, next) {
        let index = 0;
        
        const runMiddleware = async (i) => {
            if (i >= this.middlewares.length) {
                return next();
            }
            
            const middleware = this.middlewares[i];
            
            try {
                await middleware(to, from, (nextParam) => {
                    if (nextParam) {
                        console.log('🛑 [MIDDLEWARE MANAGER] 检测到重定向，停止执行后续中间件', nextParam);
                        return next(nextParam);
                    }
                    return runMiddleware(i + 1);
                });
            } catch (error) {
                console.error(`❌ [MIDDLEWARE MANAGER] 第${i + 1}个中间件执行出错:`, error);
                return next();
            }
        };
        
        await runMiddleware(0);
    }
}

export const middlewareManager = new MiddlewareManager(); 