import { defineStore } from 'pinia';
import { getAccessToken } from '../../utils/auth';
import { UserInfo } from '../../models/user-models';

export const useUserStore = defineStore('user', {
    state: () => ({
        userInfo: null as UserInfo | null, // 使用强类型定义
    }),
    getters: {
        /**
         * 判断用户是否已登录
         * @param state - Pinia state
         * @returns {boolean} - 如果 userInfo 存在且包含有效信息（例如 token 或 uid），则返回 true
         */
        isLoggedIn(state): boolean {
            // 您可以根据 userInfo 中的具体字段来判断登录状态
            // 确保 state.userInfo 存在后才访问其属性
            return !!state.userInfo && state.userInfo.id != 0 && !!getAccessToken();
        },
        /**
         * 获取当前用户信息
         * @param state - Pinia state
         * @returns {UserInfo | null} - 当前用户信息对象或 null
         */
        currentUser(state): UserInfo | null {
            return state.userInfo;
        },
        /**
         * 判断当前用户是否是管理员
         * @param state - Pinia state
         * @returns {boolean} - 如果当前用户是管理员则返回true
         */
        isAdmin(state): boolean {
            return !!state.userInfo && !!state.userInfo.is_admin;
        }
    },
    actions: {
        /**
         * 设置用户信息
         * @param {any} info - 用户信息对象或 null
         */
        setUserInfo(info: any) {
            if (info === null) {
                this.userInfo = null;
            } else if (info instanceof UserInfo) {
                this.userInfo = info;
            } else {
                // 如果传入的是普通对象，转换为UserInfo实例
                this.userInfo = UserInfo.fromJson(info);
            }
        },
        /**
         * 清除用户信息 (登出时使用)
         */
        clearUserInfo() {
            this.userInfo = null;
            
            // 清空媒体相关数据
            try {
                const { useMediaListStore } = require('@/store/modules/media-list');
                const mediaStore = useMediaListStore();
                mediaStore.clearAllData();
            } catch (error) {
                console.warn('Failed to clear media data on logout:', error);
            }
        },
    },
    /**
     * 配置持久化
     * 默认情况下，这将使用 localStorage 将整个 store 的 state 持久化。
     * `key` 是存储在 localStorage 中的键名，默认为 store 的 id ('user')。
     */
    persist: {
        key: 'user-store', // 自定义存储键名
        storage: localStorage, // window.sessionStorage 或自定义存储引擎
        // 序列化和反序列化配置，确保 UserInfo 类实例正确恢复
        serializer: {
            serialize: (state: any) => {
                return JSON.stringify({
                    userInfo: state.userInfo ? state.userInfo.toJson() : null
                });
            },
            deserialize: (value: string) => {
                const parsed = JSON.parse(value);
                return {
                    userInfo: parsed.userInfo ? UserInfo.fromJson(parsed.userInfo) : null
                };
            }
        }
    },
});

