import { ApiClient } from './client-api';
import { API_MODEL_AVAILABLE } from './api-url';
import { AvailableModelsResponseInfo } from '../models/chat-model-models';
import type { ApiResponse } from './definitions';

/**
 * 聊天模型相关API服务
 * 提供聊天模型查询等功能
 */
export class ApiChatModel {
    /**
     * 获取可用模型列表
     * @returns Promise<ApiResponse<AvailableModelsResponseInfo>> 模型列表响应
     */
    static async getAvailableModels(): Promise<ApiResponse<AvailableModelsResponseInfo>> {
        return await ApiClient.post(
            API_MODEL_AVAILABLE,
            {},
            AvailableModelsResponseInfo
        );
    }
}