/**
 * 认证相关中间件
 */
import { getAccessToken } from '@/utils/auth';
import { ROUTER_PATHS, ROUTER_PERMISSION } from '../constants';

/**
 * 登录验证中间件
 * @param {Object} to - 目标路由
 * @param {Object} from - 来源路由
 * @param {Function} next - 导航函数
 */
export const middleware_auth = async (to, from, next) => {
    const token = getAccessToken();
    const permissionLevel = to.meta?.permissionLevel || ROUTER_PERMISSION.PUBLIC;
    
    // 公开页面直接通过
    if (permissionLevel === ROUTER_PERMISSION.PUBLIC) {
        return next();
    }
    
    // 需要登录但未登录
    if (!token && permissionLevel !== ROUTER_PERMISSION.PUBLIC) {
        const redirectInfo = { 
            path: ROUTER_PATHS.LOGIN, 
            query: { redirect: to.fullPath } 
        };
        return next(redirectInfo);
    }
    
    console.log('🛡️ [AUTH MIDDLEWARE] ✅ Auth 验证通过，继续执行');
    next();
};