/**
 * 用户相关API服务
 * 提供用户登录等功能
 */
import { ApiClient } from './client-api';
import { UserLoginInfo, UserInfo } from '../models/user-models';
import { GenericResponseData } from '../models/base-models';
import { ApiResponse } from './definitions';
import { API_AUTH_LOGIN, API_USER_ACCOUNT_INFO, API_AUTH_RESET_PASSWORD_REQUEST, API_AUTH_RESET_PASSWORD } from './api-url';
import { useUserStore } from '../store/modules/user';
import { useChatModelStore } from '../store/modules/chat-model';
import { useConversationStore } from '../store/modules/conversation';
import { removeToken, setToken } from '../utils/auth';
import { storageInit } from '../utils/storage';

/**
 * 用户API服务类
 * 集中管理所有用户相关的API调用
 */
export class ApiUser {
    /**
     * 用户登录
     * @param email 用户邮箱
     * @param password 用户密码
     * @returns 登录结果，包含token和用户基本信息
     */
    static async login(email: string, password: string): Promise<ApiResponse<UserLoginInfo>> {
        const res = await ApiClient.post(
            API_AUTH_LOGIN,
            { email, password },
            UserLoginInfo
        );

        setToken({
            access_token: res.data.access_token,
            token_type: res.data.token_type || 'bearer'
        });

        try{
            const accountRes = await this.getUserAccountInfo();
            const userStore = useUserStore();
            userStore.setUserInfo(accountRes.data);
            storageInit(accountRes.data.id.toString(),false);
        }catch(e){
            console.error('Failed to fetch user account info:', e);
            return Promise.reject(e);
        }
        
        return res;
    }

    /**
     * 退出登录
     */
    static async logout() {
        // todo pxy 需要调用接口

        const userStore = useUserStore();
        const chatModelStore = useChatModelStore();
        const conversationStore = useConversationStore();
        userStore.clearUserInfo();
        removeToken();    
        chatModelStore.clearModels();
        conversationStore.clearAllConversationCache();
    }

    /**
     * 获取当前用户账户信息
     * @returns 用户账户信息，包含邮箱、昵称、创建时间等
     */
    static async getUserAccountInfo(): Promise<ApiResponse<UserInfo>> {
        return await ApiClient.post(
            API_USER_ACCOUNT_INFO,
            {},
            UserInfo
        );   
    }

    /**
     * 请求重置密码
     * 发送验证码到用户邮箱
     * @param email 用户邮箱地址
     * @returns 请求结果
     */
    static async requestResetPassword(email: string): Promise<ApiResponse<GenericResponseData>> {
        return await ApiClient.post(
            API_AUTH_RESET_PASSWORD_REQUEST,
            { email },
            GenericResponseData
        );
    }

    /**
     * 重置密码
     * 通过邮箱验证码重置用户密码
     * @param email 用户邮箱地址
     * @param verifyCode 邮箱验证码
     * @param newPassword 新密码
     * @param confirmPassword 确认新密码
     * @returns 重置密码结果
     */
    static async resetPassword(
        email: string, 
        verifyCode: string, 
        newPassword: string, 
        confirmPassword: string
    ): Promise<ApiResponse<GenericResponseData>> {
        return await ApiClient.post(
            API_AUTH_RESET_PASSWORD,
            { 
                email, 
                verify_code: verifyCode, 
                new_password: newPassword, 
                confirm_password: confirmPassword 
            },
            GenericResponseData
        );
    }
} 