import { defineStore } from 'pinia';
import { ref } from 'vue';
import { ApiChatModel } from '../../api/api-chat-model';
import { MODEL_CAPABILITIES, AvailableModelsResponseInfo } from '../../models/chat-model-models';
import type { ModelInfo, ModelQuery, ModelCapabilityType } from '../../models/chat-model-models';

interface mediaModelsInfo {
  value: string;
  label: string;
  description: string;
}

/**
 * 聊天模型管理 Store
 * 提供模型数据的统一管理和查询功能
 * 支持本地存储、重试机制和请求限制
 */
export const useChatModelStore = defineStore('chatModel', () => {
    // 配置常量
    const STORAGE_KEY = 'chat_models_data';
    const RETRY_KEY = 'chat_models_retry';
    const MAX_RETRY = 5;
    const COOLDOWN_TIME = 5 * 60 * 1000; // 5分钟

    // 状态定义
    const modelsResponse = ref<AvailableModelsResponseInfo>(new AvailableModelsResponseInfo());
    const isLoading = ref(false);

    /**
     * 获取重试信息
     */
    const getRetryInfo = () => {
        try {
            const data = localStorage.getItem(RETRY_KEY);
            return data ? JSON.parse(data) : { count: 0, lastFail: 0 };
        } catch {
            return { count: 0, lastFail: 0 };
        }
    };

    /**
     * 检查是否可以请求
     */
    const canRequest = () => {
        const retry = getRetryInfo();
        if (retry.count < MAX_RETRY) return true;
        
        const timePassed = Date.now() - retry.lastFail;
        if (timePassed >= COOLDOWN_TIME) {
            localStorage.removeItem(RETRY_KEY);
            return true;
        }
        return false;
    };

    /**
     * 从本地存储加载数据
     */
    const loadFromStorage = () => {
        try {
            const data = localStorage.getItem(STORAGE_KEY);
            if (data) {
                const parsed = JSON.parse(data);
                const instance = new AvailableModelsResponseInfo();
                instance.models = parsed.models || [];
                modelsResponse.value = instance;
                return true;
            }
        } catch (error) {
            console.warn('Failed to load from storage:', error);
        }
        return false;
    };

    /**
     * 保存到本地存储
     */
    const saveToStorage = () => {
        try {
            localStorage.setItem(STORAGE_KEY, JSON.stringify({
                models: modelsResponse.value.models,
                timestamp: Date.now()
            }));
        } catch (error) {
            console.warn('Failed to save to storage:', error);
        }
    };

    /**
     * 初始化模型数据
     */
    const initModels = async (): Promise<void> => {
        if (isLoading.value || !canRequest()) return;
        
        isLoading.value = true;
        try {
            const response = await ApiChatModel.getAvailableModels();
            modelsResponse.value = response.data;
            saveToStorage();
            localStorage.removeItem(RETRY_KEY); // 成功后重置重试
            console.log(`Models loaded: ${modelsResponse.value.models.length} models`);
        } catch (error) {
            // 记录失败
            const retry = getRetryInfo();
            localStorage.setItem(RETRY_KEY, JSON.stringify({
                count: retry.count + 1,
                lastFail: Date.now()
            }));
            console.error('Failed to load models:', error);
            throw error;
        } finally {
            isLoading.value = false;
        }
    };

    /**
     * 确保数据已加载
     */
    const ensureData = async (): Promise<void> => {
        // 先从本地加载（如果没有数据的话）
        if (modelsResponse.value.models.length === 0) {
            loadFromStorage();
        }
        
        // 如果有数据了，异步更新；如果没有数据，等待接口返回
        if (modelsResponse.value.models.length > 0) {
            // 有本地数据时，异步更新不阻塞
            initModels().catch(error => {
                console.warn('Background model update failed:', error);
            });
        } else {
            // 没有本地数据时，等待接口返回
            await initModels();
        }
    };

    /**
     * 查询模型
     */
    const getModels = async (query?: ModelQuery): Promise<ModelInfo[]> => {
        await ensureData();
        return query ? modelsResponse.value.getModelsByCapabilities(query) : modelsResponse.value.models;
    };

    /**
     * 根据能力获取模型
     */
    const getModelsByCapability = async (capability: ModelCapabilityType): Promise<ModelInfo[]> => {
        return getModels(capability);
    };

    // 便捷方法
    const getTextModels = () => getModelsByCapability(MODEL_CAPABILITIES.TEXT);
    const getVisionModels = () => getModelsByCapability(MODEL_CAPABILITIES.VISION);
    const getImageGenModels = () => getModelsByCapability(MODEL_CAPABILITIES.IMAGE_GEN);
    const getReasoningModels = () => getModelsByCapability(MODEL_CAPABILITIES.REASONING);
    const getImageAnalysisModels = () => getModelsByCapability(MODEL_CAPABILITIES.IMAGE_ANALYSIS);
    const getDeepSearchModels = () => getModelsByCapability(MODEL_CAPABILITIES.DEEP_SEARCH);
    const getVideoGenModels = () => getModelsByCapability(MODEL_CAPABILITIES.VIDEO_GEN);
    
    const getMediaModels =  async () => {
      const models = await getModelsByCapability(MODEL_CAPABILITIES.IMAGE_GEN)
      const mediaModels:mediaModelsInfo[] = []
      models.forEach(model => {
        mediaModels.push({
            value: model.name,
            label: model.name,
            description: ''
        })
      })
      return mediaModels
    };

    /**
     * 获取视频生成模型（格式化为媒体模型信息）
     * @returns {Promise<mediaModelsInfo[]>} 视频生成模型列表
     */
    const getVideoMediaModels = async () => {
      const models = await getModelsByCapability(MODEL_CAPABILITIES.VIDEO_GEN);
      const videoModels: mediaModelsInfo[] = [];
      models.forEach(model => {
        videoModels.push({
            value: model.name,
            label: model.name,
            description: ''
        });
      });
      return videoModels;
    };

    // 文生图模型获取 (image-generation + text-to-image)
    const getTextToImageModels = async () => {
      const models = await getModelsByCapability(MODEL_CAPABILITIES.IMAGE_GEN)
      const mediaModels:mediaModelsInfo[] = []
      models.forEach(model => {
        mediaModels.push({
            value: model.name,
            label: model.name,
            description: ''
        })
      })
      return mediaModels
    };

    // 图生图模型获取 (image-generation + image-to-image)  
    const getImageToImageModels = async () => {
      const models = await getModelsByCapability(MODEL_CAPABILITIES.IMAGE_GEN)
      const mediaModels:mediaModelsInfo[] = []
      models.forEach(model => {
        mediaModels.push({
            value: model.name,
            label: model.name,
            description: ''
        })
      })
      return mediaModels
    };

    // 文生视频模型获取 (video-generation + text-to-video)
    const getTextToVideoModels = async () => {
      const models = await getModelsByCapability(MODEL_CAPABILITIES.VIDEO_GEN)
      const mediaModels:mediaModelsInfo[] = []
      models.forEach(model => {
        mediaModels.push({
            value: model.name,
            label: model.name,
            description: ''
        })
      })
      return mediaModels
    };

    // 图生视频模型获取 (video-generation + picture-to-video)
    const getPictureToVideoModels = async () => {
      const models = await getModelsByCapability(MODEL_CAPABILITIES.VIDEO_GEN)
      const mediaModels:mediaModelsInfo[] = []
      models.forEach(model => {
        mediaModels.push({
            value: model.name,
            label: model.name,
            description: ''
        })
      })
      return mediaModels
    };

    // 初始化时加载本地数据
    loadFromStorage();

    const clearModels = () => {
      localStorage.removeItem(RETRY_KEY);
      localStorage.removeItem(STORAGE_KEY);
    };

    return {
        // 状态
        models: modelsResponse,
        isLoading,
        
        // 方法
        initModels,
        getModels,
        getModelsByCapability,
        getTextModels,
        getVisionModels,
        getImageGenModels,
        getReasoningModels,
        getImageAnalysisModels,
        clearModels,
        getMediaModels,
        getVideoGenModels,
        getVideoMediaModels,
        getDeepSearchModels,
        getTextToImageModels,
        getImageToImageModels,
        getTextToVideoModels,
        getPictureToVideoModels
    };
}); 