/**
 * 路由入口文件 - 优化版本
 */
import { createRouter, createWebHistory } from 'vue-router';
import { routes } from './routers';
import { middleware_auth } from './middlewares/middle-auth';
import { middleware_permission } from './middlewares/middle-permission';
import { middlewareManager } from './middlewares';

// 创建路由实例
const router = createRouter({
    // 使用History模式
    history: createWebHistory(),
    routes
});

// 注册中间件
middlewareManager
    .use(middleware_auth)
    .use(middleware_permission);

// 全局前置导航守卫
router.beforeEach((to, from, next) => {
    // 设置页面标题
    if (to.meta?.title) {
        document.title = to.meta.title;
    }

    // 执行中间件链
    middlewareManager.execute(to, from, next);
});

// 路由导航完成后的钩子
router.afterEach((to, from, failure) => {
    if (failure) {
        console.error('🏁 [ROUTER] 导航失败:', failure);
    }
});

// 路由错误处理
router.onError((error) => {
    console.error('💥 [ROUTER] 路由错误:', error);
});

export default router;