import { BaseResponseData } from './base-models';

/**
 * 聊天模型能力常量定义
 * 统一管理所有模型能力标识符
 */
export const MODEL_CAPABILITIES = {
    TEXT: 'text',
    REASONING: 'reasoning', 
    DEEP_SEARCH: 'deepsearch',
    VISION: 'vision',
    IMAGE_GEN: 'image_gen',
    IMAGE_ANALYSIS: 'image_analysis',
    VIDEO_GEN: 'video_gen'
} as const;

/**
 * 模型能力类型
 */
export type ModelCapabilityType = typeof MODEL_CAPABILITIES[keyof typeof MODEL_CAPABILITIES];

/**
 * 模型能力信息
 * 定义模型支持的各种功能
 */
export class ModelCapabilityInfo {
    /** 是否支持文本生成 */
    text: boolean = false;
    /** 是否支持推理功能 */
    reasoning: boolean = false;
    /** 是否支持深度搜索 */
    deepsearch: boolean = false;
    /** 是否支持图像理解 */
    vision: boolean = false;
    /** 是否支持图像生成 */
    image_gen: boolean = false;
    /** 是否支持图片分析 */
    image_analysis: boolean = false;
    /** 是否支持视频生成 */
    video_gen: boolean = false;
}

/**
 * 模型信息
 * 包含模型的基本信息和能力描述
 */
export class ModelInfo{
    /** 模型别名 */
    name: string = '';
    /** 模型能力 */
    capabilities: ModelCapabilityInfo
}

/**
 * 可用模型响应信息
 * API 返回的数据结构
 */
export class AvailableModelsResponseInfo extends BaseResponseData {
    /** 模型列表 */
    models: ModelInfo[] = [];

    /**
     * 根据模型能力获取对应的模型信息
     * @param capabilities 模型能力，可以是单个能力或多个能力数组
     * @returns 符合条件的模型列表
     */
    getModelsByCapabilities(capabilities: ModelQuery): ModelInfo[] {
        // 将单个能力转换为数组格式，便于统一处理
        const targetCapabilities = Array.isArray(capabilities) ? capabilities : [capabilities];
        
        return this.models.filter(model => {
            if (!model.capabilities) {
                return false;
            }

            // 检查模型是否支持任一指定能力
            return targetCapabilities.some(capability => 
                model.capabilities[capability as keyof ModelCapabilityInfo] === true
            );
        });
    }
}

/**
 * 模型查询参数类型
 * 支持单个能力或多个能力组合查询
 */
export type ModelQuery = ModelCapabilityType | ModelCapabilityType[]; 