import mitt, { Emitter } from 'mitt';
import { TaskType } from './media-task-polling';

/**
 * 媒体任务事件类型定义
 * 用于媒体任务轮询过程中的事件通信
 */
type MediaTaskEvents = {
  'task-status-update': { 
    taskId: string; 
    type: TaskType; 
    status: string; 
    res?: any; // 完整的状态响应数据
  };
  'task-completed': { 
    taskId: string; 
    type: TaskType; 
    result?: any; 
  };
  'task-failed': { 
    taskId: string; 
    type: TaskType; 
    error: string; 
  };
};

/**
 * 媒体任务事件总线
 * 负责媒体任务相关事件的发布和订阅
 */
export const mediaTaskEventBus: Emitter<MediaTaskEvents> = mitt<MediaTaskEvents>();

/**
 * 清除所有媒体任务事件监听器
 * 用于组件销毁时的清理工作
 */
export const clearMediaTaskEventListeners = () => {
  mediaTaskEventBus.off('task-completed');
  mediaTaskEventBus.off('task-failed');
  mediaTaskEventBus.off('task-status-update');
};

// 导出事件类型，便于其他模块使用
export type { MediaTaskEvents };

