import { defineStore } from 'pinia';

export const useConversationStore = defineStore('conversation', {
    state: () => ({
        // 存储会话列表数据
        conversations: [],
        // 存储会话详情的缓存，使用会话ID作为键
        // 新结构：{ [conversationId]: { messages: [], hasMore: boolean, cursor: string|null } }
        conversationDetails: {},
        // 当前选中的会话ID
        currentConversationId: null,
        // 页码信息
        lastId: 0,
        pageSize: 20,
        hasMore: true,
        // 记录缓存访问时间的Map，用于确定最旧的缓存
        cacheAccessTimes: {},
        // 缓存数量上限
        MAX_CACHE_SIZE: 100,
        // 会话列表最大数量限制
        MAX_CONVERSATIONS_SIZE: 100,
        // 单个会话详情最大消息数量限制
        MAX_MESSAGES_PER_CONVERSATION: 100,
        // 总缓存数据大小限制（字节）
        MAX_TOTAL_CACHE_SIZE: 5 * 1024 * 1024, // 5MB
        // 当前缓存总大小
        currentCacheSize: 0,
        // 是否已加载过会话历史接口
        hasLoadedHistory: false,
    }),
    getters: {
        // 获取当前选中的会话
        currentConversation: (state) => {
            if (!state.currentConversationId) return null;
            return state.conversations.find(c => c.id === state.currentConversationId) || null;
        },

        // 获取指定会话的详情（返回完整缓存对象，包含消息和分页信息）
        getConversationDetail: (state) => (conversationId) => {
            // 更新访问时间
            if (state.conversationDetails[conversationId]) {
                state.cacheAccessTimes[conversationId] = Date.now();
                return state.conversationDetails[conversationId];
            }
            return null;
        },

        // 检查指定会话是否已缓存详情
        hasConversationDetail: (state) => (conversationId) => {
            return !!(state.conversationDetails[conversationId] && state.conversationDetails[conversationId].messages);
        },

        // 获取当前会话数量
        conversationCount: (state) => {
            return state.conversations.length;
        },

        // 检查会话数量是否接近上限
        isConversationCountNearLimit: (state) => {
            const ratio = state.conversations.length / state.MAX_CONVERSATIONS_SIZE;
            return ratio >= 0.9; // 当达到90%时认为接近上限
        },
        // 获取当前选中的会话ID
        getCurrentConversationId: (state) => {
            return state.currentConversationId;
        }
    },

    actions: {
        // 设置会话列表
        setConversations(conversations) {
            if (!Array.isArray(conversations)) {
                console.warn('setConversations: 无效的会话数据');
                this.conversations = [];
                return;
            }

            // 检查会话数量是否超过上限
            if (conversations.length > this.MAX_CONVERSATIONS_SIZE) {
                const excessCount = conversations.length - this.MAX_CONVERSATIONS_SIZE;
                console.log(`设置的会话数量超过上限(${this.MAX_CONVERSATIONS_SIZE})，只保留最新的${this.MAX_CONVERSATIONS_SIZE}条会话`);
                
                // 只保留最新的会话（假设传入的数组已按时间排序）
                this.conversations = conversations.slice(excessCount, this.MAX_CONVERSATIONS_SIZE);
                console.log(`已设置${this.conversations.length}条会话`);
            } else {
                this.conversations = conversations;
                console.log(`已设置${conversations.length}条会话`);
            }
        },

        // 追加会话列表
        appendConversations(conversations) {
            if (!Array.isArray(conversations) || conversations.length === 0) {
                console.warn('appendConversations: 无效的会话数据');
                return;
            }

            // 合并新会话到现有列表前面（保持时间倒序）
            const newConversations = [...conversations, ...this.conversations];
            
            // 检查会话数量是否超过上限
            if (newConversations.length > this.MAX_CONVERSATIONS_SIZE) {
                const excessCount = newConversations.length - this.MAX_CONVERSATIONS_SIZE;
                console.log(`会话数量超过上限(${this.MAX_CONVERSATIONS_SIZE})，移除${excessCount}条最旧的会话`);
                
                // 获取被移除的会话ID，清理对应的缓存
                const removedConversations = newConversations.slice(0, excessCount);
                removedConversations.forEach(conversation => {
                    if (conversation.id) {
                        this.clearConversationCache(conversation.id);
                        // 如果被移除的会话是当前选中的会话，清除当前会话ID
                        if (this.currentConversationId === conversation.id) {
                            this.currentConversationId = null;
                        }
                    }
                });
                
                // 只保留最新的会话
                this.conversations = newConversations.slice(excessCount, newConversations.length);
                console.log(`保留最新的${this.MAX_CONVERSATIONS_SIZE}条会话，当前会话总数: ${this.conversations.length}`);
            } else {
                this.conversations = newConversations;
                console.log(`追加${conversations.length}条会话，当前会话总数: ${this.conversations.length}`);
            }
        },

        // 设置当前会话ID
        setCurrentConversationId(id) {
            this.currentConversationId = id;
        },

        // 设置分页信息
        setPageInfo(page, hasMore) {
            this.lastId = page;
            this.hasMore = hasMore;
        },

        // 设置已加载会话历史状态
        setHasLoadedHistory(loaded) {
            this.hasLoadedHistory = loaded;
        },

        // 重置会话历史加载状态
        resetHistoryLoadState() {
            this.hasLoadedHistory = false;
            this.conversations = [];
            this.lastId = 0;
            this.hasMore = true;
        },

        // 计算数据大小（字节）
        calculateDataSize(data) {
            try {
                return new Blob([JSON.stringify(data)]).size;
            } catch (error) {
                console.warn('计算数据大小失败:', error);
                return JSON.stringify(data).length * 2; // 粗略估算
            }
        },

        // 优化会话详情数据
        optimizeConversationDetail(detail) {
            if (!Array.isArray(detail) || detail.length === 0) {
                return detail;
            }

            // 如果消息数量超过限制，只保留最新的消息
            if (detail.length > this.MAX_MESSAGES_PER_CONVERSATION) {
                console.log(`会话消息数量超过限制(${this.MAX_MESSAGES_PER_CONVERSATION})，进行截取优化`);
                return detail.slice(-this.MAX_MESSAGES_PER_CONVERSATION);
            }

            // 优化消息内容，移除不必要的字段
            return detail.map(message => ({
                id: message.id,
                content: message.content,
                reasoning_content: message.reasoning_content,
                hasThinking: message.hasThinking,
                thinking_status: message.thinking_status,
                hasDeepSearch: message.hasDeepSearch,
                isSearching: message.isSearching,
                search_citations: message.search_citations,
                role: message.role,
                isMarkdown: message.isMarkdown,
                showLoading: false,
                typing: false,
                noStyle: true,
                placement: message.placement,
                maxWidth: message.maxWidth
            }));
        },

        // 检查并清理过多的缓存
        checkAndCleanCache() {
            const cacheSize = Object.keys(this.conversationDetails).length;
            console.log('当前缓存数量:', cacheSize);
            console.log('当前缓存大小:', (this.currentCacheSize / 1024 / 1024).toFixed(2), 'MB');

            // 检查数量限制
            if (cacheSize > this.MAX_CACHE_SIZE) {
                console.log('缓存数量超过限制，开始清理最旧数据');
                this.removeOldestCache(cacheSize - this.MAX_CACHE_SIZE);
            }

            // 检查大小限制
            if (this.currentCacheSize > this.MAX_TOTAL_CACHE_SIZE) {
                console.log('缓存大小超过限制，开始清理数据');
                this.cleanCacheBySize();
            }
        },

        // 按大小清理缓存
        cleanCacheBySize() {
            const targetSize = this.MAX_TOTAL_CACHE_SIZE * 0.8; // 清理到80%
            const sortedIds = Object.keys(this.cacheAccessTimes).sort((a, b) => {
                return this.cacheAccessTimes[a] - this.cacheAccessTimes[b];
            });

            let cleanedSize = 0;
            const idsToRemove = [];

            for (const id of sortedIds) {
                if (this.currentCacheSize - cleanedSize <= targetSize) break;

                const dataSize = this.calculateDataSize(this.conversationDetails[id]);
                cleanedSize += dataSize;
                idsToRemove.push(id);
            }

            idsToRemove.forEach(id => {
                delete this.conversationDetails[id];
                delete this.cacheAccessTimes[id];
            });

            this.currentCacheSize -= cleanedSize;
            console.log(`按大小清理了${idsToRemove.length}条缓存，释放${(cleanedSize / 1024 / 1024).toFixed(2)}MB`);
        },

        // 移除最旧的N条缓存
        removeOldestCache(count) {
            // 按访问时间排序
            const sortedIds = Object.keys(this.cacheAccessTimes).sort((a, b) => {
                return this.cacheAccessTimes[a] - this.cacheAccessTimes[b];
            });

            // 删除最旧的count条记录
            const idsToRemove = sortedIds.slice(0, count);
            let removedSize = 0;

            idsToRemove.forEach(id => {
                const dataSize = this.calculateDataSize(this.conversationDetails[id]);
                removedSize += dataSize;
                delete this.conversationDetails[id];
                delete this.cacheAccessTimes[id];
            });

            this.currentCacheSize -= removedSize;
            console.log(`已清理${idsToRemove.length}条最旧的缓存数据，释放${(removedSize / 1024 / 1024).toFixed(2)}MB`);
        },

        // 缓存会话详情（优化版本，支持分页信息）
        cacheConversationDetail(conversationId, detail, hasMore = false, cursor = null) {
            // 数据预处理和优化
            const optimizedDetail = this.optimizeConversationDetail(detail);

            // 创建新的缓存对象结构
            const cacheData = {
                messages: optimizedDetail,
                hasMore: hasMore,
                cursor: cursor
            };

            // 使用统一的缓存更新方法
            this._updateConversationCache(conversationId, cacheData, true);

            console.log(`缓存会话${conversationId}，数据大小: ${(this.calculateDataSize(cacheData) / 1024).toFixed(2)}KB，消息数量: ${optimizedDetail?.length || 0}，hasMore: ${hasMore}`);
        },

        // 添加消息到会话缓存（支持单条或多条消息）
        addMessageToConversation(conversationId, messages) {
            // 统一处理输入参数，支持单条消息或消息数组
            const messageArray = Array.isArray(messages) ? messages : [messages];

            if (messageArray.length === 0) {
                console.warn('没有消息需要添加');
                return Array.isArray(messages) ? [] : null;
            }

            // 优化消息数据
            const optimizedMessages = this._optimizeMessages(messageArray);

            // 如果会话缓存不存在，创建新的缓存
            if (!this.conversationDetails[conversationId]) {
                this.conversationDetails[conversationId] = {
                    messages: [],
                    hasMore: false,
                    cursor: null
                };
                this.cacheAccessTimes[conversationId] = Date.now();
            }

            // 获取现有消息列表
            const existingMessages = [...(this.conversationDetails[conversationId].messages || [])];

            // 对每条新消息进行去重处理
            optimizedMessages.forEach(newMessage => {
                const existingIndex = existingMessages.findIndex(msg => msg.id === newMessage.id);
                if (existingIndex !== -1) {
                    // 如果消息已存在，更新内容而不是重复添加
                    console.log(`更新已存在的消息 ID: ${newMessage.id}`);
                    existingMessages[existingIndex] = newMessage;
                } else {
                    // 如果消息不存在，添加到末尾
                    console.log(`添加新消息 ID: ${newMessage.id}`);
                    existingMessages.push(newMessage);
                }
            });

            // 保持原有的分页信息
            const cacheData = {
                messages: existingMessages,
                hasMore: this.conversationDetails[conversationId].hasMore,
                cursor: this.conversationDetails[conversationId].cursor
            };

            // 使用统一的缓存更新方法
            this._updateConversationCache(conversationId, cacheData, false);

            const actionType = messageArray.length == 1 ? '处理消息' : `批量处理${messageArray.length}条消息`;
            console.log(`${actionType}到会话${conversationId}，当前消息数: ${this.conversationDetails[conversationId].messages.length}`);

            // 如果原始输入是单条消息，返回单条优化后的消息；否则返回数组
            return Array.isArray(messages) ? optimizedMessages : optimizedMessages[0];
        },

        // 更新会话中的特定消息
        updateMessageInConversation(conversationId, messageId, updatedContent) {
            if (!this.conversationDetails[conversationId] || !this.conversationDetails[conversationId].messages) {
                console.warn(`会话${conversationId}不存在，无法更新消息`);
                return null;
            }

            const messages = this.conversationDetails[conversationId].messages;
            const messageIndex = messages.findIndex(msg => msg.id === messageId);

            if (messageIndex === -1) {
                console.warn(`消息${messageId}在会话${conversationId}中不存在`);
                return null;
            }

            // 更新消息内容
            const updatedMessage = {
                ...messages[messageIndex],
                ...updatedContent,
                timestamp: Date.now()
            };

            messages[messageIndex] = updatedMessage;

            // 更新访问时间
            this.cacheAccessTimes[conversationId] = Date.now();

            console.log(`更新会话${conversationId}中的消息${messageId}`);
            return updatedMessage;
        },

        // 统一的缓存更新方法（私有方法）
        _updateConversationCache(conversationId, newData, isFullReplace = false) {
            // 计算旧数据大小
            const oldDataSize = this.conversationDetails[conversationId]
                ? this.calculateDataSize(this.conversationDetails[conversationId])
                : 0;

            // 应用消息数量限制
            let finalData = { ...newData };
            if (Array.isArray(newData.messages) && newData.messages.length > this.MAX_MESSAGES_PER_CONVERSATION) {
                const excessCount = newData.messages.length - this.MAX_MESSAGES_PER_CONVERSATION;
                finalData.messages = newData.messages.slice(excessCount); // 保留最新的消息
                if (!isFullReplace) {
                    console.log(`会话${conversationId}消息数量超限，移除${excessCount}条旧消息`);
                }
            }

            // 计算新数据大小
            const newDataSize = this.calculateDataSize(finalData);

            // 检查单个会话数据大小
            if (newDataSize > 1024 * 1024) { // 1MB
                console.warn(`会话${conversationId}数据较大: ${(newDataSize / 1024 / 1024).toFixed(2)}MB`);
            }

            // 更新缓存
            this.conversationDetails[conversationId] = finalData;
            this.cacheAccessTimes[conversationId] = Date.now();

            // 更新总缓存大小
            this.currentCacheSize = this.currentCacheSize - oldDataSize + newDataSize;

            // 检查并清理过多的缓存
            this.checkAndCleanCache();
        },

        // 优化消息数组（私有方法）
        _optimizeMessages(messageArray) {
            return messageArray.map(message => ({
                id: message.id,
                content: message.content,
                reasoning_content: message.reasoning_content,
                hasThinking: message.hasThinking,
                thinking_status: message.thinking_status,
                hasDeepSearch: message.hasDeepSearch,
                isSearching: message.isSearching,
                search_citations: message.search_citations,
                role: message.role,
                isMarkdown: message.isMarkdown,
                showLoading: message.showLoading || false,
                typing: message.typing || false,
                noStyle: message.noStyle !== false,
                placement: message.placement,
                maxWidth: message.maxWidth,
                timestamp: message.timestamp || Date.now()
            }));
        },

        // 获取会话中的最后一条消息
        getLastMessageInConversation(conversationId) {
            const conversation = this.conversationDetails[conversationId];
            if (!conversation || !conversation.messages || conversation.messages.length === 0) {
                return null;
            }
            return conversation.messages[conversation.messages.length - 1];
        },

        // 获取会话消息数量
        getConversationMessageCount(conversationId) {
            const conversation = this.conversationDetails[conversationId];
            return conversation && conversation.messages ? conversation.messages.length : 0;
        },

        // 清除指定会话的缓存
        clearConversationCache(conversationId) {
            if (this.conversationDetails[conversationId]) {
                const dataSize = this.calculateDataSize(this.conversationDetails[conversationId]);
                this.currentCacheSize -= dataSize;
                delete this.conversationDetails[conversationId];
                delete this.cacheAccessTimes[conversationId];
                console.log(`清除会话${conversationId}缓存，释放${(dataSize / 1024).toFixed(2)}KB`);
            }
        },

        // 清除所有会话缓存
        clearAllConversationCache() {
            this.conversationDetails = {};
            this.cacheAccessTimes = {};
            this.currentCacheSize = 0;
            this.conversations = [];
        },

        // 更新会话标题
        updateConversationTitle(conversationId, title) {
            const conversation = this.conversations.find(c => c.id === conversationId);
            if (conversation) {
                conversation.title = title;
            }
        },

        // 删除会话
        deleteConversation(conversationId) {
            this.conversations = this.conversations.filter(c => c.id !== conversationId);
            this.clearConversationCache(conversationId);
            if (this.currentConversationId === conversationId) {
                this.currentConversationId = null;
            }
        }
    }
});