/**
 * AI媒体相关数据模型
 * 包含文生图、视频生成等AI媒体功能的数据模型
 */
import { BaseResponseData } from './base-models';

/**
 * AI媒体图片生成响应数据模型
 */
export class AIMediaImageModel extends BaseResponseData {
    id: string = '';
    taskId?: string;
    status: 'pending' | 'processing' | 'completed' | 'failed' = 'pending';
    imageUrl?: string;
    progress?: number;
    error?: string;
    createdAt: string = '';
    completedAt?: string;
    
    // 生成参数信息
    prompt?: string;
    model?: string;
    resolution?: string;
    ratio?: string;
    seed?: number;

    /**
     * 检查是否生成完成
     */
    get isCompleted(): boolean {
        return this.status === 'completed';
    }

    /**
     * 检查是否生成失败
     */
    get isFailed(): boolean {
        return this.status === 'failed';
    }

    /**
     * 检查是否正在处理中
     */
    get isProcessing(): boolean {
        return this.status === 'processing' || this.status === 'pending';
    }

    /**
     * 获取显示状态文本
     */
    get statusText(): string {
        const statusMap = {
            pending: 'Pending',
            processing: 'Processing',
            completed: 'Completed',
            failed: 'Failed'
        };
        return statusMap[this.status] || 'Unknown';
    }
}

/**
 * AI模型选项数据模型
 */
export class AIModelOption extends BaseResponseData {
    value: string = '';
    label: string = '';
    description?: string;
    disabled?: boolean;
    
    /**
     * 检查模型是否可用
     */
    get isAvailable(): boolean {
        return !this.disabled;
    }
}

/**
 * AI媒体模型列表响应
 */
export class AIMediaModelsResponse extends BaseResponseData {
    models: AIModelOption[] = [];
    
    /**
     * 获取可用的模型
     */
    get availableModels(): AIModelOption[] {
        return this.models.filter(model => model.isAvailable);
    }
    
    /**
     * 根据值查找模型
     */
    findModelByValue(value: string): AIModelOption | undefined {
        return this.models.find(model => model.value === value);
    }
}

