/**
 * 生成任务信息数据模型
 */
export class GenerationTaskInfo extends BaseResponseData {
    /** 任务ID */
    task_id: string = '';
    /** 生成类型 */
    generation_type: string = '';
    /** 任务状态 */
    status: string = '';
    /** 提示词 */
    prompt: string = '';
    /** 负面提示词 */
    negative_prompt?: string = '';
    /** 使用的模型 */
    model?: string = '';
    /** 生成参数 */
    parameters?: Record<string, any> = {};
    /** 创建时间 */
    created_at: string = '';
    /** 完成时间 */
    completed_at?: string = '';
    /** 是否收藏 */
    is_favorite: boolean = false;

    /**
     * 检查是否已完成
     */
    get isCompleted(): boolean {
        return this.status === 'completed';
    }

    /**
     * 检查是否失败
     */
    get isFailed(): boolean {
        return this.status === 'failed';
    }

    /**
     * 获取格式化的创建时间
     */
    get formattedCreatedAt(): string {
        return new Date(this.created_at).toLocaleDateString();
    }
}

/**
 * 生成媒体项数据模型
 */
export class GeneratedMediaItem extends BaseResponseData {
    /** 媒体ID */
    media_id: string = '';
    /** 媒体类型 */
    media_type: 'image' | 'video' = 'image';
    /** 媒体URL */
    media_url: string = '';
    /** 缩略图URL */
    thumbnail_url?: string = '';
    /** 文件大小 */
    file_size?: number = 0;
    /** 宽度 */
    width?: number = 0;
    /** 高度 */
    height?: number = 0;
    /** 时长（视频） */
    duration?: number = 0;
    /** 格式 */
    format?: string = '';
    /** 创建时间 */
    created_at: string = '';

    /**
     * 获取格式化的文件大小
     */
    get formattedFileSize(): string {
        if (!this.file_size) return '';
        
        const units = ['B', 'KB', 'MB', 'GB'];
        let size = this.file_size;
        let unitIndex = 0;
        
        while (size >= 1024 && unitIndex < units.length - 1) {
            size /= 1024;
            unitIndex++;
        }
        
        return `${size.toFixed(1)} ${units[unitIndex]}`;
    }

    /**
     * 获取格式化的分辨率
     */
    get formattedResolution(): string {
        return this.width && this.height ? `${this.width}x${this.height}` : '';
    }

    /**
     * 获取格式化的时长
     */
    get formattedDuration(): string {
        if (!this.duration) return '';
        
        const minutes = Math.floor(this.duration / 60);
        const seconds = this.duration % 60;
        return `${minutes}:${seconds.toString().padStart(2, '0')}`;
    }
}

/**
 * 生成结果项数据模型
 */
export class GenerationResultItem extends BaseResponseData {
    /** 任务信息 */
    task: GenerationTaskInfo = new GenerationTaskInfo();
    /** 生成的媒体列表 */
    media_list: GeneratedMediaItem[] = [];

    /**
     * 获取第一个媒体项
     */
    get firstMedia(): GeneratedMediaItem | null {
        return this.media_list.length > 0 ? this.media_list[0] : null;
    }

    /**
     * 获取图像媒体列表
     */
    get imageMediaList(): GeneratedMediaItem[] {
        return this.media_list.filter(media => media.media_type === 'image');
    }

    /**
     * 获取视频媒体列表
     */
    get videoMediaList(): GeneratedMediaItem[] {
        return this.media_list.filter(media => media.media_type === 'video');
    }

    /**
     * 检查是否包含图像
     */
    get hasImages(): boolean {
        return this.imageMediaList.length > 0;
    }

    /**
     * 检查是否包含视频
     */
    get hasVideos(): boolean {
        return this.videoMediaList.length > 0;
    }
}

/**
 * 收藏列表响应数据模型
 */
export class FavoritesListResponse extends BaseResponseData {
    /** 生成历史列表 */
    items: GenerationResultItem[] = [];
    /** 总数量 */
    total: number = 0;
    /** 当前页码 */
    page: number = 1;
    /** 每页数量 */
    page_size: number = 20;
    /** 是否有更多数据 */
    has_more: boolean = false;

    /**
     * 获取图像类型的结果
     */
    get imageResults(): GenerationResultItem[] {
        return this.items.filter(item => item.hasImages);
    }

    /**
     * 获取视频类型的结果
     */
    get videoResults(): GenerationResultItem[] {
        return this.items.filter(item => item.hasVideos);
    }

    /**
     * 检查是否为空
     */
    get isEmpty(): boolean {
        return this.items.length === 0;
    }

    /**
     * 获取总页数
     */
    get totalPages(): number {
        return Math.ceil(this.total / this.page_size);
    }

    /**
     * 检查是否为第一页
     */
    get isFirstPage(): boolean {
        return this.page === 1;
    }

    /**
     * 检查是否为最后一页
     */
    get isLastPage(): boolean {
        return this.page >= this.totalPages;
    }
}

/**
 * 生成历史列表响应数据模型
 * 与收藏列表结构相同，但语义不同，单独定义
 */
export class GenerationHistoryListResponse extends BaseResponseData {
    /** 生成历史列表 */
    items: GenerationResultItem[] = [];
    /** 总数量 */
    total: number = 0;
    /** 当前页码 */
    page: number = 1;
    /** 每页数量 */
    page_size: number = 20;
    /** 是否有更多数据 */
    has_more: boolean = false;

    /**
     * 获取图像类型的结果
     */
    get imageResults(): GenerationResultItem[] {
        return this.items.filter(item => item.hasImages);
    }

    /**
     * 获取视频类型的结果
     */
    get videoResults(): GenerationResultItem[] {
        return this.items.filter(item => item.hasVideos);
    }

    /**
     * 获取已完成的结果
     */
    get completedResults(): GenerationResultItem[] {
        return this.items.filter(item => item.task.isCompleted);
    }

    /**
     * 获取失败的结果
     */
    get failedResults(): GenerationResultItem[] {
        return this.items.filter(item => item.task.isFailed);
    }

    /**
     * 获取处理中的结果
     */
    get processingResults(): GenerationResultItem[] {
        return this.items.filter(item => 
            item.task.status === 'pending' || item.task.status === 'processing'
        );
    }

    /**
     * 检查是否为空
     */
    get isEmpty(): boolean {
        return this.items.length === 0;
    }

    /**
     * 获取总页数
     */
    get totalPages(): number {
        return Math.ceil(this.total / this.page_size);
    }

    /**
     * 检查是否为第一页
     */
    get isFirstPage(): boolean {
        return this.page === 1;
    }

    /**
     * 检查是否为最后一页
     */
    get isLastPage(): boolean {
        return this.page >= this.totalPages;
    }

    /**
     * 按创建时间排序
     */
    get sortedByDate(): GenerationResultItem[] {
        return [...this.items].sort((a, b) => 
            new Date(b.task.created_at).getTime() - new Date(a.task.created_at).getTime()
        );
    }

    /**
     * 按状态分组
     */
    get groupedByStatus(): Record<string, GenerationResultItem[]> {
        return this.items.reduce((groups, item) => {
            const status = item.task.status;
            if (!groups[status]) {
                groups[status] = [];
            }
            groups[status].push(item);
            return groups;
        }, {} as Record<string, GenerationResultItem[]>);
    }
}

